
import { FeatureModeUpdatedInterface } from "../Common/FeatureModeUpdatedInterface";
import { droppingPlannerSetting, droppingSizeSetting } from "../DroppingBlock/DroppingPlannerSettingInterface";
import { IDataFromHttpGet } from "../history/HistoryFromHttpGet.interface";
import { CampaignData } from "../Promo/CampaignDataInterface";
import { serverProto } from "../Protobuf/new_proto";
import { IEnterRSItemSpinMode, IUpdateRSItemUseCount, RSServerStatus } from "../RewardSystem/RewardSystem.Interface";
import { reelRollingSizeSetting, rollingPlannerSetting, singleRollingSizeSetting } from "../RollingReel/RollingPlannerStiingInterface";
import { SlotSpinLogicDisplay } from "../SpinControl/SlotSpinLogicCtrlInterface";
import type { IBurstModeFinishedPayload, IBurstModeStartPayload, IBurstModeStatusPayload } from "../BurstMode/IBurstMode.interface";
import { IMessageData } from "../Tool/message/MessageBoxInterface";
import { IGameCustomData } from "../Tool/util/IGameCustomData";

/** 存放replay spin result的session storage key */
export const ApWebReplaySessionKey = "AP_REPLAY_RESULT"
/** 存放history detail的session storage key */
export const ApWebHistoryDetailSessionKey = "AP_HISTORY_DETAIL"
export const ApWebCustomPlatformKey = 'customGamekey';
export type ApWebType =
    "ap-none" | // 無模式: 直接使用遊戲的介面, web不會覆蓋遊戲
    "ap-bridge" | // 橋接模式: 維持遊戲的介面, web部分只轉送server封包
    "ap-cover" | // 覆蓋模式: 關掉遊戲的介面, web覆蓋遊戲上當作主介面, web與遊戲都可以傳送server封包
    "ap-history" | // 歷史頁面模式: 從ticket跟history detail的http get來的資料顯示在歷史頁面, 會傳HistoryDetailData, HistoryDetailLoaded
    "ap-replay" | // 重播模式: 從ticket跟history detail的http get來的資料顯示在重播頁面, 會傳HistoryBetValueForShow
    "ap-replay-game-ui" | // 包含遊戲UI的重播模式: 會有原本cocos的遊戲UI, 其餘規則同ap-replay, 會傳HistoryBetValueForShow
    "ap-master" // 主控模式: web完全控制遊戲, 包含介面與server封包


export type SpinModeType = `bf${number}` | "bf" | `bc${number}` | "dc" | "eb" | `eb${number}` | "" | null;

export interface BetDataTournamentInterface {
    /** 競賽ID */
    id: string;
    /** 競賽房間ID */
    roomId: string;
    /** 競賽額外費用 */
    feeRatio: number;
    /**
     * 額外下注金額: 扣掉基礎下注後的額外金額 (不包含伺服器的1000倍)
     * ex: Bet: 1000, Tournament Rate: 0.2, 額外下注金額就是 200
     * 如果是double chance, 就是乘上1.2后的額外下注金額
     * ex: Bet: 1000, Tournament Rate: 0.2, Double Chance: true, 額外下注金額就是 240
    */
    extra?: number;
}

export interface BetDataInterface {
    /** 都是傳原始的Bet, (不計算bf的50或是dc的1.2, 不包含伺服器的1000倍) */
    bet?: number,
    /** 不包含伺服器的1000倍的Bet數字 */
    betList?: number[],
    /** 目前的Bet索引 */
    betIndex?: number | null,
    /** 是否購買Feature */
    isBuyFeature?: boolean,
    /** 是否開啟雙倍機會 */
    isDoubleChance?: boolean,
    /** Feature模式名稱 */
    modeName?: SpinModeType,
    /** 正在啟用的Campaign, null/undefined表示使用cashWallet */
    campaignId?: string | null,
    /** 是否為競賽下注 */
    tournament?: BetDataTournamentInterface | null;
}

export interface HistoryDetailDataInterface {
    ticketId: string;
    bet: number;
    win: number;
    /** 結束的Balance */
    balance: number;
    lineNumber: number;
    spinResult: serverProto.Ispin_result;
}

/** 定義Slot遊戲類型 */
export type LineTypeString = "One_Line" | "Line" | "Line_way" | "Way" | "Eliminate" | "Orignial_Game_Default";

/** 定義Bottom Panel */
export type BottomPanelStyleString = "default" | "ghana" | "none";

export interface IClickIntoMainGameData {
    gameVersion: string;
    slotGameType: LineTypeString;
    lineRule: number[][];
    bottomPanelStyle: BottomPanelStyleString;
}

/** 更新遊戲顯示的資料，包括玩家餘額和免費旋轉次數 */
export interface GameDisplayData {
    balance: number;
    freeSpinCount?: {
        total: number;
        remain: number;
    };
}

export type GamePopupCategory = "rewardSystemMain" | "rewardSystemLevelUp" | "cashDropMain" |"cashDropDialog"| "cashDropPickup" | "promo" | "messageBox" | "other" | "featureTransition" | "bigWinTransition" | "inGameSelection";

export interface  InGamePopupOpened {
    category: GamePopupCategory;
}

export interface InGamePopupClosed {
    category: GamePopupCategory;
    /** 是否啟用spin按鈕的lighting-effect, 未提供時預設為true */
    enableLightingEffect?: boolean;    
}

/** 可以依照後續OG新增, 增加新的指令 */
export type WebCommandType = "bet" | "go" | "cashout" | "difficulty" | string;

/** 定義所有ApWeb跟Iframe之間的通訊訊息 */
export interface ApWebMessageMap {
    // Socket相關的訊息
    /** Cocos: Cocos準備好跟ApWebSocket溝通了 */
    SocketWakeUp: undefined;
    // ApWeb: Socket狀態改變, 會傳送SocketOnOpen, SocketOnClose, SocketOnError, SocketOnMessage
    SocketOnOpen: undefined;
    SocketOnClose: { code: number; reason: string };
    SocketOnError: undefined;
    SocketOnMessage: { data: any };
    /** Cocos: 透過ApWebSocket傳送訊息給ApWeb */
    SocketSend: { data: string | BufferSource | Blob };
    /** Cocos: 透過ApWebSocket關閉連線狀態通知ApWeb */
    SocketClose: { code: number; reason: string };

    // 功能相關訊息, Cocos <-> ApWeb
    /** Cocos: 開始載入, 是Loading第一幀畫面顯示的時候 */
    GameOnLoad: undefined;
    /** Cocos: 遊戲自訂設定 */
    GameCustomSetting: { customData: IGameCustomData };
    /** Cocos: 目前遊戲畫面比例 */
    GameAspectRatio: { aspectRatio: "landscape" | "portrait" };
    /** ApWeb: 設定Cocos橫向螢幕比例參數 */
    UpdatelandscapeAspectRatio: { aspectRatio: number };
    /** Cocos: 載入完成, 是遊戲第一幀畫面顯示的時候 */
    LoadingFinished: undefined;
    /** Cocos: 點擊進入主遊戲 */
    ClickIntoMainGame: IClickIntoMainGameData;
    /** ApWeb: 設定Cocos連線token, url */
    SetupConnection: { authToken: string, url: string };
    /** Cocos: 變更下注金額 */
    BetChanged: {betIndex: number, bet: number};
    /** Cocos: 變更下注模式 */
    BetModeChanged: {modeName: SpinModeType};
    /** Cocos: 音樂音量變更 */
    MusicChanged: { volume: number };
    /** Cocos: 音效音量變更 */
    SoundChanged: { volume: number };
    /** Cocos: Win 直接更新到web */
    WinMoneyUpdated: { win: number };
    /** Cocos: Balance 直接更新到web, 目前暫時沒開放此功能, 請改用BalanceUpdated  */
    BalanceUpdated: { cashWallet: number };
    /** Cocos: Balance 增加, 傳送增加的金額到web */
    BalanceAdded: { amount: number };
    /** Cocos: 顯示最終Balance */
    FinalBalanceShown: undefined;
    /** Cocos: Feature Mode是否啟動 */
    FeatureModeEnabled: { enabled: boolean };
    /** Cocos: Feature Mode狀態更新 */
    FeatureModeUpdated: FeatureModeUpdatedInterface;
    /** ApWeb: 更新下注相關資料 */
    UpdateBetData: BetDataInterface;
    /** ApWeb: 網頁端點擊Spin按鈕 (開始進行遊戲) */
    ClickSpin: {betData?: BetDataInterface, useInGameResult?: boolean};
    /** ApWeb: 網頁端點擊命令按鈕 (Bet, Go, Cashout...) */
    ClickCommand: {command: WebCommandType, param: any};
    /** Cocos: 開始Spin, 同時傳送遊戲模式字串 */
    StartSpinning: {gameString: string};
    /** ApWeb: 點擊急停會傳到遊戲端 */
    ImmediatelyStop: undefined;
    /** Cocos: 準備好可以Spin或是其他功能 (本輪遊戲表演結束) */
    ReadyForSpin: undefined;
    /** ApWeb: 傳給遊戲端Spin結果 */
    SpinResult: serverProto.Ispin_result;
    /** ApWeb: 要求遊戲更新UI顯示 */
    SlotSpinLogicDisplay: SlotSpinLogicDisplay;
    /** Cocos: 點擊Buy Feature會傳送這給上層ApWeb */
    BuyFeature: undefined;
    /** Cocos: 點擊Open Promo會傳送這給上層ApWeb */
    OpenPromo: undefined;
    /** Cocos: 網址重定向 */
    UrlRedirection: {url: string};
    /** Cocos: 跳出訊息 */
    GameMessageBox: {data: IMessageData}
    /** Cocos: 要求開啟Info頁面 */
    OpenInfo: undefined;
    /** ApWeb: 更新遊戲顯示的資料，包括玩家餘額和免費旋轉次數 */
    UpdateDisplayData: { displayData: GameDisplayData };
    /** Cocos: 設定使用的RS Slot Item */
    RSEnterRSItemSpinMode: IEnterRSItemSpinMode;
    /** Cocos: 離開RS Item Spin模式 */
    RSLeaveRSItemSpinMode: boolean;
    /** Cocos: 更新RS Item剩餘可用次數 */
    RSUpdateUseItemCount:IUpdateRSItemUseCount;
    /** Cocos: 獎勵系統有新的通知 */
    RSHasNewNotification: { notified: boolean };
    /** Apweb: 開啟獎勵系統 */
    WebOpenRS: { enabled: boolean };


    /** Cocos: 獎勵系統伺服器狀態更新 */
    ChangeRSServerStatus: { status: RSServerStatus };
    /** Cocos: 遊戲彈出視窗開啟 */
    InGamePopupOpened: InGamePopupOpened;
    /** Cocos: 遊戲彈出視窗關閉 */
    InGamePopupClosed: InGamePopupClosed;
    /** Cocos: 設定Web UI 的互動狀態 */
    SetWebInteraction: { enabled: boolean };
    /** Cocos: 是否正在長按 */
    IsPressHolding: { holding: boolean };

    /** ApWeb: 更新Campaigns, 已有ID覆蓋, 新ID新增 */
    UpdateCampaigns: { campaigns: CampaignData[] };
    /** Cocos: 選擇Campaign, 使用現金請用null */
    SelectCampaign: { campaignId: string | null };
    /** ApWeb: 選擇指定Campaign, 使用現金請用null */
    UseCampaign: { campaignId: string | null; type?: 'freeSpins' | 'freeBonus'; campaignWalletId?: number };
    /** ApWeb: 企劃調整滾輪參數 */
    RollingSetting: rollingPlannerSetting;
    /** ApWeb: 企劃調整掉落參數 */
    DroppingSetting: droppingPlannerSetting;
    /** ApWeb: 企劃調整掉落輪軸大小參數 */
    DroppingSizeSetting: droppingSizeSetting;
    /** ApWeb: 企劃調整軸滾輪大小參數 */
    ReelRollingSizeSetting: reelRollingSizeSetting;
    /** ApWeb: 企劃調整單滾輪大小參數 */
    singleRollingSizeSetting: singleRollingSizeSetting;
    /** ApWeb: 調整遊戲內參數 */
    GameParameterSetting: {debugWinScore: number, debugWinType: number};
    /** ApWeb: 調整遊戲demo test case用 */
    GameDemoTestCase: {demoTestCaseName: string | null};
    /** ApWeb: 變更History頁面索引 */
    ChangeHistoryPageIndex: { pageIndex: number };
    /** ApWeb: 切換遊戲速度, 目前支援三種速度 */
    SetSpinType: { speed: 0 | 1 | 2 };
    /** ApWeb: 開關音樂 */
    SetMusic: { enabled: boolean };
    /** ApWeb: 開關音效 */
    SetSound: { enabled: boolean };
    /** Cocos: Replay模式 下注值for show, Replay才會送 */
    HistoryBetValueForShow:{bet: number,currencySymbol:string};
    /** Cocos: History模式, cocos HttpGet到就會傳送 */
    HistoryDetailData: IDataFromHttpGet;
    /** Cocos: History模式 Detail 畫面出現 (如果有多個Round會多次傳送)*/
    HistoryDetailLoaded: HistoryDetailDataInterface;
    /** Cocos: SharedReplay模式 dev環境下, 通知上層已準備好接收Session Data */
    ReadyForSessionData: string;
    /** ApWeb: 傳送Session Data給Cocos (dev環境SharedReplay用) */
    SessionData: { [key: string]: string };

    // BurstMode 掃蕩相關訊息
    /** ApWeb: 啟動掃蕩模式 */
    StartBurstMode: IBurstModeStartPayload;
    /** ApWeb: 請求停止掃蕩（等本把結束後停）*/
    StopBurstMode: undefined;
    /** Cocos: 掃蕩每把結束後狀態更新 */
    BurstModeUpdated: IBurstModeStatusPayload;
    /** Cocos: 掃蕩結束 */
    BurstModeFinished: IBurstModeFinishedPayload;
}
